package sem

import (
	"errors"
	"testing"
)

func TestTrail164MountAddedBetweenResolvers(t *testing.T) {
	previous := activeMountTable.Load()
	t.Cleanup(func() { activeMountTable.Store(previous) })
	beginMountTableScope()
	points := map[string]struct{}{"/": {}}
	read := func() (map[string]struct{}, error) { return points, nil }
	if _, err := cachedMountPoints(read); err != nil { t.Fatal(err) }
	// A later independent metadata validation has no beginMountTableScope.
	points = map[string]struct{}{"/": {}, "/workspace/repo/nested": {}}
	cached, err := cachedMountPoints(read)
	if err != nil { t.Fatal(err) }
	freshGuard := makePathMountGuard("/", "/workspace/repo", points)
	if !errors.Is(freshGuard.beforeLookup("workspace/repo/nested"), errPathCrossesKnownMount) {
		t.Fatal("fresh guard did not reject mount")
	}
	cachedGuard := makePathMountGuard("/", "/workspace/repo", cached)
	if err := cachedGuard.beforeLookup("workspace/repo/nested"); !errors.Is(err, errPathCrossesKnownMount) {
		t.Fatalf("cached guard permits lookup of newly mounted path: %v", err)
	}
}

